import json, itertools
def solve(ti):
    H,W=len(ti),len(ti[0])
    g=[row[:] for row in ti]
    pts=[(i,j) for i in range(H) for j in range(W) if ti[i][j]==2]
    # pair consecutive points along each row and each column
    from collections import defaultdict
    rows=defaultdict(list); cols=defaultdict(list)
    for p in pts: rows[p[0]].append(p); cols[p[1]].append(p)
    def mark(a,b):
        (r1,c1),(r2,c2)=a,b
        if r1==r2 or c1==c2: return False
        others=[p for p in pts if p not in (a,b) and min(r1,r2)<p[0]<max(r1,r2) and min(c1,c2)<p[1]<max(c1,c2)]
        if others: return False
        rr0,rr1=min(r1,r2),max(r1,r2); cc0,cc1=min(c1,c2),max(c1,c2)
        for j in range(cc0,cc1+1):
            if g[rr0][j]==0: g[rr0][j]=3
            if g[rr1][j]==0: g[rr1][j]=3
        for i in range(rr0,rr1+1):
            if g[i][cc0]==0: g[i][cc0]=3
            if cc0!=cc1 and g[i][cc1]==0: g[i][cc1]=3
        return True
    done=set()
    while True:
        new=set()
        for (a,b) in itertools.combinations(pts,2):
            if {a,b}<=done: continue
            if mark(a,b): new.add({a,b})
        if not new: break
        done|=new
    return g
